{
  "name": "QuTech CC 中央控制器（核心）",
  "name_en": "QuTech Central Controller (CC) Core",
  "manufacturer": "QuTech",
  "description": "用于量子实验（尤其是超导量子比特）的硬件序列与定时控制器核心模块。它负责加载并执行序列程序，通过数字后背板与 CCIO 模块和 VSM 等外设交互，提供DIO链路校准、边沿延时校准、触发与运行控制，以及状态/事件监控与报告。",
  "description_en": "Core hardware sequencer and timing controller for quantum experiments (notably superconducting qubits). It loads and executes sequence programs, interfaces via digital backplane with CCIO modules and VSM, performs DIO link calibration, edge-delay tuning, trigger/run control, and comprehensive status/event monitoring.",
  "actions": [
    {
      "action_name": "auto-assemble",
      "description": "将序列程序源码汇编为可在控制器上执行的指令。",
      "description_en": "Assemble the sequence program source into executable instructions on the controller."
    },
    {
      "action_name": "auto-assemble_and_start",
      "description": "汇编序列程序并立即启动执行。",
      "description_en": "Assemble the sequence program and start execution immediately."
    },
    {
      "action_name": "auto-calibrate_dio",
      "description": "对选定的 CCIO 执行 DIO 链路校准，根据期望比特模式测量对齐与裕量。",
      "description_en": "Perform DIO link calibration on the selected CCIO using an expected bit pattern to determine alignment and margins."
    },
    {
      "action_name": "auto-debug_get_ccio_reg",
      "description": "读取指定 CCIO 的寄存器（调试）。",
      "description_en": "Read a register from the specified CCIO (debug)."
    },
    {
      "action_name": "auto-debug_get_ccio_trace",
      "description": "获取指定 CCIO 的调试跟踪数据。",
      "description_en": "Fetch the debug trace data from the specified CCIO."
    },
    {
      "action_name": "auto-debug_get_traces",
      "description": "按掩码获取控制器/CCIO 的调试轨迹数据。",
      "description_en": "Retrieve combined debug traces from the controller/CCIO using a mask."
    },
    {
      "action_name": "auto-debug_marker_in",
      "description": "在指定 CCIO 位上使能调试标记输入路径。",
      "description_en": "Enable a debug marker input path on the specified CCIO bit."
    },
    {
      "action_name": "auto-debug_marker_off",
      "description": "关闭指定 CCIO 的调试标记路由。",
      "description_en": "Disable the debug marker routing on the specified CCIO."
    },
    {
      "action_name": "auto-debug_marker_out",
