      "action_name": "auto-print_status_questionable",
      "description": "打印合并的“可疑”状态信息汇总。",
      "description_en": "Print the combined 'questionable' status summary."
    },
    {
      "action_name": "auto-sequence_program_assemble",
      "description": "设置（上传）待汇编的序列程序源码。",
      "description_en": "Set (upload) the sequence program source to assemble."
    },
    {
      "action_name": "auto-set_q1_reg",
      "description": "设置所选 CCIO 的 Q1 寄存器（需在停止状态）。",
      "description_en": "Set the Q1 register of the selected CCIO (requires the controller to be stopped)."
    },
    {
      "action_name": "auto-set_seqbar_cnt",
      "description": "设置所选 CCIO 的 seqbar 计数值。",
      "description_en": "Set the seqbar count for the selected CCIO."
    },
    {
      "action_name": "auto-set_status_operation_run_enable",
